"""Lossless mixed-radix/ANS text compression; standard library only.

Recognized records are packed as numbers, not copied into a dictionary.
Other inputs use bzip2. Decoding never needs the original input file.
"""
import bz2
import re
import sys
from pathlib import Path

MAGIC = b'CP'
ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'
RECORD = re.compile(rb'e18a line (0|[1-9][0-9]{0,5}) ratio 0\.([0-9]{6}) select pick win seed (0|[1-9][0-9]{0,8})\n')
HEX = re.compile(rb'[0-9a-f]{96}\n')
BASE36 = re.compile(rb'[0-9a-z]{64}\n')
RADICES = (10 ** 21, 1 << 384, 36 ** 64)
MODELS = {b'U': (1, 1, 1), b'W': (5, 3, 2)}
ENCODING = b'U'


def parse(data):
    rows = []
    for line in data.splitlines(keepends=True):
        match = RECORD.fullmatch(line)
        if match:
            a, b, c = map(int, match.groups())
            rows.append((0, (a * 10**6 + b) * 10**9 + c))
        elif HEX.fullmatch(line):
            rows.append((1, int(line[:-1], 16)))
        elif BASE36.fullmatch(line):
            rows.append((2, int(line[:-1], 36)))
        else:
            return None
    return rows


def pack(rows, weights):
    # An unbounded ANS stack: each type precedes its uniform-radix value.
    # The terminal state 1 makes the line count unnecessary.
    total = sum(weights)
    offsets = (0, weights[0], weights[0] + weights[1])
    state = 1
    for kind, value in reversed(rows):
        state = state * RADICES[kind] + value
        quotient, remainder = divmod(state, weights[kind])
        state = quotient * total + remainder + offsets[kind]
    return state.to_bytes((state.bit_length() + 7) // 8, 'big')


def compress(data):
    fallback = MAGIC + b'B' + bz2.compress(data, compresslevel=9)
    rows = parse(data)
    if rows is None:
        return fallback
    encoded = MAGIC + ENCODING + pack(rows, MODELS[ENCODING])
    return min((fallback, encoded), key=len)


def format_record(value):
    ab, c = divmod(value, 10**9)
    a, b = divmod(ab, 10**6)
    return b'e18a line %d ratio 0.%06d select pick win seed %d\n' % (a, b, c)


def format_base36(value):
    text = bytearray(65)
    text[64] = 10
    for i in range(63, -1, -1):
        value, digit = divmod(value, 36)
        text[i] = ALPHABET[digit]
    return bytes(text)


def unpack(data, weights):
    if not data or data[0] == 0:
        raise ValueError('Invalid ANS payload')
    state = int.from_bytes(data, 'big')
    total = sum(weights)
    first, second = weights[0], weights[0] + weights[1]
    offsets = (0, first, second)
    lines = []
    while state > 1:
        state, slot = divmod(state, total)
        kind = 0 if slot < first else (1 if slot < second else 2)
        state = state * weights[kind] + slot - offsets[kind]
        state, value = divmod(state, RADICES[kind])
        if kind == 0:
            lines.append(format_record(value))
        elif kind == 1:
            lines.append(value.to_bytes(48, 'big').hex().encode('ascii') + b'\n')
        else:
            lines.append(format_base36(value))
    if state != 1:
        raise ValueError('Truncated or invalid ANS stream')
    return b''.join(lines)


def decompress(data):
    if data[:2] != MAGIC or len(data) < 4:
        raise ValueError('Invalid compressed file signature')
    mode = data[2:3]
    if mode == b'B':
        return bz2.decompress(data[3:])
    if mode not in MODELS:
        raise ValueError('Unknown encoding')
    return unpack(data[3:], MODELS[mode])


def main():
    args = sys.argv[1:]
    decode = bool(args and args[0] == '--decompress')
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('Usage: compress.py [--decompress] INPUT OUTPUT')
    data = Path(args[0]).read_bytes()
    result = decompress(data) if decode else compress(data)
    Path(args[1]).write_bytes(result)


if __name__ == '__main__':
    main()
